                h0w8i := mulmod(h0w8i, h0w80, q)
                c0Value := addmod(
                    c0Value,
                    mulmod(calldataload(pEval_s3), h0w8i, q),
                    q
                )

                res := addmod(
                    res,
                    mulmod(
                        c0Value,
                        mulmod(num, mload(add(pMem, add(pLiS0Inv, 160))), q),
                        q
