                h0w8i := mulmod(h0w8i, h0w80, q)
                c0Value := addmod(
                    c0Value,
                    mulmod(calldataload(pEval_s1), h0w8i, q),
                    q
                )
                h0w8i := mulmod(h0w8i, h0w80, q)
                c0Value := addmod(
                    c0Value,
                    mulmod(calldataload(pEval_s2), h0w8i, q),
